import Foundation
import OrcaBridge

/// One option definition from the generated schema (pinned-engine
/// print_config_def, regenerated by Bridge/tools/build-extract-config.sh).
struct ConfigOptionSchema: Codable, Sendable {
    let key: String
    let type: Int
    let label: String?
    let fullLabel: String?
    let category: String?
    let tooltip: String?
    let guiFlags: String?
    let mode: Int?
    let sidetext: String?
    let multiline: Bool?
    let fullWidth: Bool?
    let defaultValue: String?
    let min: Double?
    let max: Double?
    let enumValues: [String]?
    let enumLabels: [String]?

    enum CodingKeys: String, CodingKey {
        case key
        case type
        case label
        case fullLabel = "full_label"
        case category
        case tooltip
        case guiFlags = "gui_flags"
        case mode
        case sidetext
        case multiline
        case fullWidth = "full_width"
        case defaultValue = "default"
        case min
        case max
        case enumValues = "enum_values"
        case enumLabels = "enum_labels"
    }
}

/// Desktop page → optgroup → option layout extracted from the pinned
/// upstream GUI source (Bridge/tools/extract_settings_layout.py).
struct SettingsLayout: Codable, Sendable {
    struct Group: Codable, Sendable {
        let title: String
        let options: [String]
    }

    struct Page: Codable, Sendable {
        let page: String
        let groups: [Group]
    }

    let source: String
    let layout: [String: [Page]]

    func pages(for kind: PresetKind) -> [Page] {
        layout[ConfigSchema.layoutKey(kind)] ?? []
    }
}

/// Client model of the generated schema + layout resources. Each is decoded
/// once per process; decode failures are typed and surface in the UI.
enum ConfigSchema {
    static let shared: Result<[ConfigOptionSchema], AppFailure> = decode(
        resource: "config-schema",
        as: [ConfigOptionSchema].self
    )

    static let index: Result<[String: ConfigOptionSchema], AppFailure> =
        shared.map { schema in
            Dictionary(uniqueKeysWithValues: schema.map { ($0.key, $0) })
        }

    static let layout: Result<SettingsLayout, AppFailure> = decode(
        resource: "settings-layout",
        as: SettingsLayout.self
    )

    static func layoutKey(_ kind: PresetKind) -> String {
        switch kind {
        case .machine: return "machine"
        case .filament: return "filament"
        case .process: return "process"
        }
    }

    private static func decode<Value: Decodable>(
        resource: String,
        as type: Value.Type
    ) -> Result<Value, AppFailure> {
        guard let url = Bundle.module.url(
            forResource: resource,
            withExtension: "json"
        ) else {
            return .failure(.invariant(
                operation: "load \(resource)",
                diagnostic: "\(resource).json is missing from the bundle"
            ))
        }
        do {
            let data = try Data(contentsOf: url)
            return .success(try JSONDecoder().decode(type, from: data))
        } catch {
            return .failure(.invariant(
                operation: "decode \(resource)",
                diagnostic: String(reflecting: error)
            ))
        }
    }

    /// Desktop-parity visibility: Simple shows comSimple only; Advanced adds
    /// comAdvanced; Expert adds comExpert (comDevelop stays engine-internal).
    static func isVisible(mode: Int, filter: SettingsModeFilter) -> Bool {
        switch filter {
        case .simple: return mode <= 0
        case .advanced: return mode <= 1
        case .expert: return mode <= 2
        }
    }
}

enum SettingsModeFilter: String, CaseIterable, Identifiable, Sendable {
    case simple = "Simple"
    case advanced = "Advanced"
    case expert = "Expert"

    var id: String { rawValue }
}

/// One editable option merged from the schema and the engine's edited config.
struct SettingsEditorRow: Identifiable, Sendable {
    let key: String
    let label: String
    let tooltip: String?
    let sidetext: String?
    let mode: Int
    let type: Int
    let multiline: Bool
    let minimum: Double?
    let maximum: Double?
    let enumValues: [String]
    let enumLabels: [String]
    let value: String
    let isModified: Bool

    var id: String { key }

    var isVector: Bool { type & 0x4000 != 0 }
    var scalarType: Int { type & ~0x4000 }

    /// Single-extruder machines store most machine/filament options as
    /// one-element vectors; edit those like scalars. Quoted string vectors
    /// keep the raw serialized editor.
    var behavesAsScalar: Bool {
        !isVector || (!value.contains(",") && scalarType != 3)
    }

    var editorKind: SettingsEditorKind {
        guard behavesAsScalar else { return .text }
        if scalarType == 3 && multiline { return .multiline }
        if !enumValues.isEmpty && (scalarType == 9 || scalarType == 2) {
            return .picker
        }
        switch scalarType {
        case 8: return .toggle
        case 1, 2, 4, 5: return .numeric
        default: return .text
        }
    }

    var boolValue: Bool {
        value == "1" || value.lowercased() == "true"
    }

    /// Validates a numeric draft against the schema range (percent options
    /// may carry a trailing "%"). Returns a human-readable rejection or nil.
    func numericRejection(for draft: String) -> String? {
        guard editorKind == .numeric else { return nil }
        let trimmed = draft.trimmingCharacters(in: .whitespaces)
        let percent = trimmed.hasSuffix("%")
        let number = percent ? String(trimmed.dropLast()) : trimmed
        guard let parsed = Double(number) else {
            return "\(label): \"\(draft)\" is not a number"
        }
        if scalarType == 2 && parsed.rounded() != parsed {
            return "\(label): an integer is required"
        }
        if percent && scalarType != 4 && scalarType != 5 {
            return "\(label): percent values are not allowed"
        }
        // Percent-or-absolute options validate only absolute values.
        if !(scalarType == 5 && percent) {
            if let minimum, minimum > -Double(Float.greatestFiniteMagnitude),
               parsed < minimum {
                return "\(label): minimum is \(Self.format(minimum))"
            }
            if let maximum, maximum < Double(Float.greatestFiniteMagnitude),
               parsed > maximum {
                return "\(label): maximum is \(Self.format(maximum))"
            }
        }
        return nil
    }

    private static func format(_ value: Double) -> String {
        value.rounded() == value ? String(Int(value)) : String(value)
    }
}

extension SettingsEditorRow {
    /// A row for an arbitrary option value (object / part overrides).
    init(schema: ConfigOptionSchema, value: String, isModified: Bool) {
        self.init(
            key: schema.key,
            label: schema.fullLabel?.isEmpty == false
                ? schema.fullLabel ?? schema.key
                : (schema.label?.isEmpty == false ? schema.label ?? schema.key : schema.key),
            tooltip: schema.tooltip?.isEmpty == false ? schema.tooltip : nil,
            sidetext: schema.sidetext?.isEmpty == false ? schema.sidetext : nil,
            mode: schema.mode ?? 0,
            type: schema.type,
            multiline: schema.multiline ?? false,
            minimum: schema.min,
            maximum: schema.max,
            enumValues: schema.enumValues ?? [],
            enumLabels: schema.enumLabels ?? [],
            value: value,
            isModified: isModified
        )
    }
}

enum SettingsEditorKind: Sendable {
    case toggle
    case picker
    case numeric
    case text
    case multiline
}

/// C-style escaping used by the engine's scalar string serialization
/// (`escape_string_cstyle`: \n, \r, \\, \"). Format adapter only.
enum ConfigStringCodec {
    static func unescape(_ serialized: String) -> String {
        var result = ""
        var iterator = serialized.makeIterator()
        while let character = iterator.next() {
            guard character == "\\" else {
                result.append(character)
                continue
            }
            switch iterator.next() {
            case "n": result.append("\n")
            case "r": result.append("\r")
            case "\\": result.append("\\")
            case "\"": result.append("\"")
            case let other?: result.append("\\"); result.append(other)
            case nil: result.append("\\")
            }
        }
        return result
    }

    static func escape(_ raw: String) -> String {
        // Iterate scalars: Swift treats CRLF as ONE Character grapheme.
        var result = ""
        for scalar in raw.unicodeScalars {
            switch scalar {
            case "\n": result += "\\n"
            case "\r": result += "\\r"
            case "\\": result += "\\\\"
            case "\"": result += "\\\""
            default: result.unicodeScalars.append(scalar)
            }
        }
        return result
    }
}
